 if(!state.reviewScanned){$(".review-layout aside").innerHTML=`<div class="scanning-state"><span class="live-dot"></span><h2>AI正在执行全文审校</h2><p>事实核查 · 表述规范 · 文字差错 · 标点规范</p><div class="scan-progress"><i></i></div></div>`;if(!state.reviewScanTimer)state.reviewScanTimer=setTimeout(()=>{state.reviewScanTimer=null;state.reviewScanned=true;if(state.page==="review")renderReview(full)},1800);return}
 const asset=full?"assets/drone-delivery-shenzhen.png":"../assets/drone-delivery-shenzhen.png";const safety=document.createElement("section");safety.className="safety-matrix";safety.innerHTML=`<div class="safety-head"><div><b>多模态安全审查</b><span>文本合规 · 事实核查 · 影像真实性 · 版权校验</span></div><span class="pill ${state.imageDecision?"tag-green":"tag-yellow"}">${state.imageDecision?"影像已处置":"1项待人工处置"}</span></div><div class="safety-grid"><article><span class="safety-icon">敏</span><b>敏感词与合规</b><p>扫描2,148字，发现绝对化表述1处，敏感词0处。</p><em>自动甄别完成</em></article><article><span class="safety-icon">实</span><b>事实谬误核查</b><p>核验6个关键事实，发现数值冲突1处、无充分信源1处。</p><em>多信源比对完成</em></article><article class="media-review"><img src="${asset}" alt="无人机配送新闻图片"><div><b>虚构影像甄别</b><p>生成式影像特征概率87%；缺少原始EXIF与摄影者信息。</p><em>${state.imageDecision==="rejected"?"已从稿件素材中移除":"需要人工复核"}</em>${state.imageDecision?"":'<button class="btn small" id="rejectImage">不采用该影像</button>'}</div></article><article><span class="safety-icon">版</span><b>版权自动比对</b><p>视觉指纹库未找到明确授权记录；相似素材3条，最高相似度82%。</p><em>${state.imageDecision==="rejected"?"风险素材已移除":"授权状态待确认"}</em></article></div>`;$(".review-layout").before(safety);$("#rejectImage")?.addEventListener("click",()=>{state.imageDecision="rejected";renderReview(full)});if(!state.imageDecision)$("#sign").disabled=true;
 if(state.signed){$("#returnDraft").disabled=true;$("#sign").disabled=true;$("#sign").textContent=`已签发 · ${state.signedAt||""}`}
