 $$("[data-edit-issue]").forEach(x=>x.onclick=()=>{const issue=D.reviewIssues.find(i=>i.id===x.dataset.editIssue);if(!issue)return;const draft=state.reviewEdits[issue.id]||issue.fix;modal("修改建议文案",`<p style="margin:0 0 10px;color:#666;font-size:13px">原文：${esc(issue.original)}</p><textarea id="editFixInput" rows="3" style="width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--line);font:inherit;resize:vertical">${esc(draft)}</textarea>`,[{label:"取消"},{label:"确认修改",primary:true,onClick:()=>{const val=($("#editFixInput")?.value||"").trim();if(!val){toast("请填写修改后的文案");return false}state.reviewDecisions[issue.id]="edit";state.reviewEdits[issue.id]=val;persist();renderReview(full)}}])});
