 const labels={wechat:["公众号","深度图文 · 结构化深读","完整报道 · 导语重写 · 小节标题"],weibo:["微博","短讯传播 · 提问互动","136/140字 · 话题标签 · 投票互动"],video:["抖音短视频","口播脚本 · 5镜分镜","5镜 · 00:24 · 竖屏字幕"],xhs:["小红书","生活视角笔记","亲测视角 · 三图 · 场景化标签"],toutiao:["头条号","资讯速览 · 算法分发","要点前置 · 关键词优化 · 信息流"]};
